"""Make photo-paired context comparisons for coarse and fine quiet/weak structure."""
from pathlib import Path

import numpy as np

from demosaic.experiments.artifacts import checked, read_json, reference, write_json

ROOT=Path(__file__).resolve().parent
OUTPUT=Path("docs/results/scene-full-epoch-v1")
BANDS=("lower","fine","upper")
POLICIES=("spatial/matching","spatial/neutral","spatial/wrong-distant","none","100k")
UNIFORM=("quiet_RGB_mean_absolute_bias_DN16","quiet_RGB_centered_RMS_DN16")
SEED=17905


def array(rows,model,band):
    if band=="flat":
        return {k:np.array([r["metrics"][model]["uniform_core"][k]for r in rows])for k in UNIFORM}
    fields=[r["metrics"][model]["band"][band]for r in rows]
    dot=np.array([r["aligned_increment_dot"]for r in fields])
    power=np.array([r["exact_paired_increment_sq"]for r in fields])
    return {key:np.array([r[key]for r in fields])for key in ("increment_RMS_DN16","quiet_RMS_DN16")}|{
        "aligned_numerator":dot,"aligned_denominator":power}


def summary(rows,model,band,resamples):
    totals=array(rows,model,band)
    if band=="flat":
        return {k:r[resamples].mean(1)for k,r in totals.items()}
    dot,power=(totals.pop(k)for k in ("aligned_numerator","aligned_denominator"))
    return {k:r[resamples].mean(1)for k,r in totals.items()}|{
        "aligned_response_pct":100*dot[resamples].sum(1)/power[resamples].sum(1)}


def main():
    before,after=(reference(ROOT/f"review-{s:06d}/pilot/results.json")for s in (7500,10000))
    rows0,rows1=(read_json(checked(r))["source_metrics"]for r in (before,after))
    def cases(rows,noise,draw):
        result=sorted((r for r in rows if r["profile"]==noise and r["draw"]==draw),key=lambda r:r["source"])
        assert len(result)==8
        return result
    rng=np.random.default_rng(SEED)
    draws=np.vstack((np.arange(8),rng.integers(8,size=(10000,8))))
    summary_rows={}
    for noise in ("iso400","iso6400"):
        for draw in ("coupled","independent"):
            a,b=(cases(rows,noise,draw)for rows in (rows0,rows1))
            assert [r["source"]for r in a]==[r["source"]for r in b]
            gains={}
            for band in (*BANDS,"flat"):
                m={policy:summary(b,policy,band,draws)for policy in POLICIES}
                prior=summary(a,"spatial/matching",band,draws)
                after_matching=m["spatial/matching"]
                options={k:v for k,v in m.items() if k!="spatial/matching"}
                options["matching-7.5k"]=prior
                deltas={}
                for key,choice in options.items():
                    effects={n:after_matching[n]-choice[n]for n in after_matching}
                    deltas[key]={k:[float(v[0]),*[float(x)for x in np.quantile(v[1:],[.025,.975])]]for k,v in effects.items()}
                gains[band]={"means":{k:{n:float(a[0])for n,a in f.items()}for k,f in m.items()},
                             "matching-minus":deltas}
            summary_rows[f"{noise}/{draw}"]=gains
    out=OUTPUT/"matched-010000-band-context.json"
    write_json(out,{"driver_source":Path(__file__).read_text(),"previous":before,"current":after,"groups":summary_rows,
        "scope":"8 fixed photo IDs and matched context interventions. Source-paired bootstrap, reused 10000 draws across each metric in the comparison."})


if __name__=="__main__":
    main()
